use vstd::prelude::*;

verus! {
    fn solve(n: i8, s: Vec<char>) -> (transitions: i8)
        requires
            n >= 0,
            s.len() == n as usize,
            forall(|i: nat| i < s.len() as nat ==> (s[i as usize] == 'U' || s[i as usize] == 'R')),
        ensures
            transitions >= 0,
            transitions <= n,
    {
        if n == 0 {
            return 0;
        }

        let mut x = 0;
        let mut y = 0;
        let mut transitions = 0;
        let mut last_region = 0; // 0 for border, 1 for Region A, 2 for Region B

        for &move_char in &s {
            match move_char {
                'U' => y += 1,
                'R' => x += 1,
                _ => unreachable!(), // Since input is guaranteed to be 'U' or 'R'
            }

            // Determine the current region
            let current_region = if x > y {
                1 // Region A
            } else if y > x {
                2 // Region B
            } else {
                0 // Border
            };

            // Count transitions only if we are not on the border
            if current_region != 0 {
                if last_region == 0 {
                    // Just left the border, do not count transition
                    last_region = current_region;
                } else if last_region != current_region {
                    // Count transition
                    transitions += 1;
                    last_region = current_region;
                }
            } else {
                // We are on the border, reset last_region
                last_region = 0;
            }
        }

        transitions
    }
}
